// SECURITY: Decrement principal by REQUESTED amount, not RECEIVED amount
// Any difference accumulates as protocol-owned yield
clientBalances[token][balanceHolder] -= amount;
totalDeposited[token] -= amount;

// Phase 1 caches balance:
state.balance = balance; // this.balanceOf at T=0

// Phase 2 passes stale cached amount:
_totalWithdraw(token, client, withdrawAmount); // withdrawAmount = state.balance from T=0

// _totalWithdraw ignores amount, uses live clientStoredBalance:
uint256 clientStoredBalance = clientBalances[token][client]; // re-reads storage
uint256 sharesToSell = (totalShares * clientStoredBalance) / totalDeposited[token];

// minOut is in shares, validated against vault rate at deposit time:
creditedPrincipal = _creditedPrincipal(amount);           // amount * (1 - slippageBps)
uint256 minOut = vault.convertToShares(creditedPrincipal); // vault internal rate
// Curve pool may quote vault shares below vault.convertToAssets:
uint256 sharesReceived = ammAdapter.swap(underlying, vault, amount, minOut);

uint256 totalValue = vault.convertToAssets(vault.balanceOf(address(this))); // snapshot
// ... _accrueSurplusShares calls vault.convertToShares per client ...
uint256 idealUnderlying = vault.convertToAssets(totalShares); // second call — may differ
uint256 minOut = idealUnderlying * (MAX_BPS - slippageToleranceBps) / MAX_BPS;

uint256 total = (totalValue * principal) / td; // proportional allocation
if (total <= principal) continue;
surplus = total - principal;

function _emergencyWithdraw(uint256 amount) internal override {
    uint256 totalShares = vault.balanceOf(address(this));
    require(totalShares > 0, "...");
    uint256 sharesToTransfer = amount < totalShares ? amount : totalShares;
    // Transfers shares to owner WITHOUT updating clientBalances or totalDeposited:
    IERC20(address(vault)).safeTransfer(owner(), sharesToTransfer);
    // clientBalances[token][*] and totalDeposited[token] are NOT touched here.
}

// Two-phase totalWithdrawal (24h timelock):
function totalWithdrawal(address token, address client) external override onlyOwner nonReentrant whenNotPaused
// -- requires Phase 1 then 24h wait then Phase 2 --

// Zero-delay withdrawAsOwner (no timelock, no pause check):
function withdrawAsOwner(address client, address recipient, uint256 amount) external onlyOwner nonReentrant {
    _withdrawInternal(address(underlyingToken), amount, recipient, client);
}

// Default value in constructor:
uint256 public slippageToleranceBps; // = 0

// With slippageBps=0, creditedPrincipal = full nominal amount:
function _creditedPrincipal(uint256 amount) internal view returns (uint256) {
    return amount * (MAX_BPS - slippageToleranceBps) / MAX_BPS; // = amount when bps=0
}

