function totalBalanceOf(address token, address account) external view override returns (uint256) {
    uint256 totalValue = vault.convertToAssets(totalShares); // live vault price
    return (totalValue * principal) / totalDeposited[token];  // can be < principalOf
}
function principalOf(address token, address account) external view override returns (uint256) {
    return clientBalances[token][account]; // static accounting value
}
